<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$sources=['https://fhir.saude.gov.br/rira/en/CodeSystem-BRCID10.json.html','https://raw.githubusercontent.com/rpzk/HealthCare/main/fixtures/01-master-data/cid10/cid10-complete.json'];$data=null;foreach($sources as $url){$ctx=stream_context_create(['http'=>['timeout'=>45,'header'=>"User-Agent: Sistema-Medico/3.0\r\n"],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);$raw=@file_get_contents($url,false,$ctx);if($raw===false)continue;if(str_ends_with($url,'.html')){$a=strpos($raw,'{');$b=strrpos($raw,'}');$raw=$a!==false&&$b>$a?substr($raw,$a,$b-$a+1):'';$raw=html_entity_decode($raw);} $j=json_decode($raw,true);if(isset($j['concept'])&&is_array($j['concept'])){$data=$j;break;}if(is_array($j)){foreach($j as $x){if(isset($x['code'],$x['description'])){$data=['concept'=>array_map(fn($z)=>['code'=>$z['code'],'display'=>$z['description']],$j)];break;}}}}if(!$data)exit('Não foi possível obter a base CID agora. Tente novamente ou verifique a saída HTTPS da hospedagem.');db()->beginTransaction();try{db()->exec('DELETE FROM cids');$q=db()->prepare('INSERT INTO cids(codigo,descricao,fonte,versao) VALUES(?,?,?,?)');foreach($data['concept'] as $c)if(!empty($c['code'])&&!empty($c['display']))$q->execute([$c['code'],$c['display'],'BRCID10',$data['version']??'']);db()->commit();audit_log('sincronizar_cid','cids',null,['quantidade'=>count($data['concept'])]);}catch(Throwable $e){db()->rollBack();exit('Falha ao salvar CID: '.e($e->getMessage()));}header('Location:/medical/cid/index.php');